Detection uses a tiered approach, from most to least reliable:

1. The explicit ``DATAHUB_CALLER`` env var override.
2. Known env var signatures present in the current process environment.
3. The parent process environment (Linux: ``/proc``, macOS: ``ps eww``),
   matched against :data:`_CALLER_SIGNATURES`.
4. Process-tree heuristics based on the ancestor command names.

The result is cached (``lru_cache(maxsize=1)``) since the invoking environment
does not change over the lifetime of a process.
"""

import functools
import logging
import os
import platform
import subprocess
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)

# Maximum length of the returned caller label. Kept well under the limit that
# consumers (e.g. the User-Agent header) can safely embed.
_MAX_CALLER_LENGTH = 200

# Timeout (seconds) for the small ``ps`` subprocesses used for process-tree
# introspection. These are cheap local calls, so a short timeout is plenty.
_SUBPROCESS_TIMEOUT_SEC = 2

# Maps environment variable signatures to caller labels. Keys are either bare
# env var names (matched by key-presence) or full "KEY=value" strings (matched
# exactly). Ordering is significant: when a parent environment string contains
# multiple matching signatures, the first match wins, so AI coding tools are
# listed before generic CI systems.
_CALLER_SIGNATURES: Dict[str, str] = {
    "CLAUDECODE": "claude-code",
    "CURSOR_TRACE_ID": "cursor",
    "LANGCHAIN_TRACING_V2": "langchain",
    "LANGSMITH_API_KEY": "langchain",
    "LANGGRAPH_API_URL": "langgraph",
    "GITHUB_ACTIONS": "github-actions",
    "JENKINS_URL": "jenkins",
}

# Shells that indicate an interactive terminal invocation.
_SHELL_NAMES = {"bash", "zsh", "fish", "sh", "dash", "tcsh", "ksh"}


def _match_signatures(env_text: str) -> Optional[str]:
    """Return the label of the first signature found in ``env_text``.

    ``env_text`` is a space- or newline-separated string of ``KEY=value`` pairs.
    For signatures without "=", a key-presence match (``f"{key}="``) is used;
    for signatures with "=", an exact substring match is used.
    """
    for signature, label in _CALLER_SIGNATURES.items():
        if "=" in signature:
            if signature in env_text:
                return label
        elif f"{signature}=" in env_text:
            return label
    return None


def _read_parent_env_linux(ppid: int) -> Optional[str]:
    """Read the environment of ``ppid`` from ``/proc/<ppid>/environ``.

    Null-byte separators are converted to newlines. Returns None if the process
    environment cannot be read.
    """
    try:
        with open(f"/proc/{ppid}/environ", "rb") as f:
            raw = f.read()
    except (PermissionError, FileNotFoundError):
        return None
    return raw.decode("utf-8", errors="replace").replace("\0", "\n")


def _read_parent_env_macos(ppid: int) -> Optional[str]:
    """Read the environment of ``ppid`` on macOS via ``ps eww``.

    Returns the command stdout if the subprocess exits successfully, else None.
    """
    try:
        result = subprocess.run(
            ["ps", "eww", "-o", "command", "-p", str(ppid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SEC,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout


def _get_process_name(pid: int) -> Optional[str]:
    """Return the basename of the command name for ``pid``.

    A Gradle daemon runs as ``java``; when we detect that, we inspect the full
    command line and report ``gradle`` instead. Returns None on failure.
    """
    try:
        result = subprocess.run(
            ["ps", "-o", "comm=", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SEC,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None

    name = os.path.basename(result.stdout.strip())

    if name == "java":
        full_command = _get_full_command(pid)
        if full_command and "GradleDaemon" in full_command:
            return "gradle"

    return name


def _get_full_command(pid: int) -> Optional[str]:
    """Return the full command line for ``pid``, stripped. None on failure."""
    try:
        result = subprocess.run(
            ["ps", "-o", "command=", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SEC,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout.strip()


def _get_parent_pid(pid: int) -> Optional[int]:
    """Return the integer parent PID of ``pid``.

    Returns None for PID 1 (init, the end of the chain) and on any failure to
    obtain a valid integer.
    """
    if pid == 1:
        return None
    try:
        result = subprocess.run(
            ["ps", "-o", "ppid=", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SEC,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    try:
        return int(result.stdout.strip())
    except ValueError:
        return None


def _get_ancestor_chain(max_depth: int = 4) -> List[str]:
    """Walk the process tree from the current process's parent upward.

    Returns the list of ancestor process names, stopping when a name or parent
    PID cannot be determined, or when ``max_depth`` names have been collected.
    """
    chain: List[str] = []
    pid: Optional[int] = os.getppid()

    while pid is not None and len(chain) < max_depth:
        name = _get_process_name(pid)
        if name is None:
            break
        chain.append(name)

        pid = _get_parent_pid(pid)
        if pid is None:
            break

    return chain


